const { tarefa } = $json;
const validar = $json.validarSomente === true || $json.validarSomente === 'true';
const VERSAO_DA_API_META = 'v26.0';
const versao = VERSAO_DA_API_META;
const TAREFAS_PEDIDAS = ['ANALYZE'];
const negocio = String(tarefa?.managerExternalId ?? '').trim();
const conta = String(tarefa?.targetExternalId ?? '').trim().toLowerCase();

const recusar = (falha) => [{ json: { tarefa: tarefa ?? {}, validar, falha } }];
if (!tarefa?.taskId) return recusar('tarefa sem identificador');
if (tarefa.kind !== 'bm_partner_request') return recusar(`tipo de tarefa desconhecido: ${tarefa.kind}`);
if (!/^\d{5,25}$/.test(negocio)) return recusar('Business Manager da agência ausente ou fora do formato numérico');
if (!/^act_\d{4,20}$/.test(conta)) return recusar('conta de anúncio fora do formato act_1234567890');

if (validar) {
  return [{ json: { tarefa, validar, conta, permitidas: TAREFAS_PEDIDAS, url: `https://graph.facebook.com/${versao}/${negocio}?fields=id,name,verification_status` } }];
}

return [{
  json: {
    tarefa,
    validar,
    conta,
    permitidas: TAREFAS_PEDIDAS,
    url: `https://graph.facebook.com/${versao}/${negocio}/client_ad_accounts`,
  },
}];

const plano = $('Planejar').first().json;
const atual = $input.first().json;
const taskId = plano.tarefa?.taskId ?? null;
const recusar = (motivo) => [{ json: { taskId, sucesso: false, outcome: String(motivo).slice(0, 500) } }];

if (plano.falha) return recusar(plano.falha);
if (atual.error) return recusar(`falha de rede: ${atual.error?.message ?? atual.error}`);

if (atual.statusCode >= 200 && atual.statusCode < 300) {
  if (plano.validar) {
    const nome = atual.body?.name ?? atual.body?.id ?? 'sem nome';
    return [{ json: { taskId, sucesso: true, outcome: `[só validação] Business Manager acessível · ${nome} · pediria ${plano.permitidas.join(',')} em ${plano.conta}`.slice(0, 500) } }];
  }
  const situacao = atual.body?.access_status ?? (atual.body?.success === true ? 'PENDING' : 'desconhecida');
  const outcome = situacao === 'CONFIRMED'
    ? `acesso confirmado · ${plano.conta} · ${plano.permitidas.join(',')}`
    : `pedido enviado · ${plano.conta} · ${plano.permitidas.join(',')} · aguardando aprovação do cliente no Business Manager dele (${situacao})`;
  return [{ json: { taskId, sucesso: true, outcome: outcome.slice(0, 500) } }];
}

const erro = atual.body?.error ?? {};
if (erro.code === 190) return recusar('credencial da Meta expirada ou revogada: reautorize o Meta Ads (código 190)');
const titulo = erro.error_user_title || erro.message || 'recusado sem mensagem';
const codigo = erro.code ? ` (código ${erro.code}${erro.error_subcode ? `/${erro.error_subcode}` : ''})` : '';
return recusar(`${titulo}${codigo} · HTTP ${atual.statusCode}`);
